// Organizational Leadership Practice Test 6. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items. HOSA facts follow the Valus Organizational
// Leadership lessons, which summarize the HOSA Handbook (Sections A–C), the HOSA website and
// The First Fifty Years 1976–2026; parliamentary items follow RONR In Brief.
import {q, mix} from './q.js';
const HB='HOSA Handbook, Sections A–C', WEB='HOSA website (Voting Delegate resources)', FFY='HOSA, The First Fifty Years 1976–2026', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const VD='Voting Delegate Role and Responsibilities', PP='Parliamentary Procedure', INC='HOSA Inc.', ORG='Organizational Structure of HOSA', HIST='History of HOSA', EC='Positions and Responsibilities of the Executive Council', MEM='Membership';

export default {
 id:'organizational-leadership-6',
 event:'Organizational Leadership',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the HOSA Handbook (Sections A–C), the HOSA website, The First Fifty Years 1976–2026 and Robert’s Rules of Order Newly Revised In Brief',
 plan:[{area:VD,weight:24},{area:PP,weight:24},{area:INC,weight:16},{area:ORG,weight:12},{area:HIST,weight:12},{area:EC,weight:8},{area:MEM,weight:4}],
 questions:mix([
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 30,000 members receive?','17',['15','16','18'],'A','4 delegates cover up to 5,000; 29,001–31,000 is the 13th added range of 2,000 members, for 17.',WEB),
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 7,001 members receive?','6',['4','5','7'],'B','5,001–7,000 earns 5 delegates, so one more member moves the association into the 7,001–9,000 range.',WEB),
  q(VD,'A newly chartered association has 20 members. How many voting delegates does the allocation table give it?','0',['1','2','3'],'C','The table lists 0 delegates for 0–25 members, so very small associations are not yet represented by a delegate.',WEB),
  q(VD,'Chartered association A has 2,000 members and B has 5,500. How many voting delegates do they have together?','8',['6','7','9'],'D','A falls in 1,001–3,000 (3 delegates), and B falls in 5,001–7,000 (5 delegates).',WEB),
  q(VD,'A candidate hands out the most popular giveaways at ILC. How should this affect a delegate’s vote?','It should not; giveaways are not qualifications',['It should count as proof of creativity','It should decide a close vote','It should count against the candidate'],'A','Being memorable for a gimmick is a common bias; focus on leadership, vision and commitment to members.',WEB),
  q(VD,'At the caucus, delegates from the same chartered association disagree about a candidate. What is the best way forward?','Return to shared criteria and evidence',['Let the loudest delegate decide','Flip a coin to settle it','Skip the discussion and leave early'],'B','A respectful discussion based on agreed criteria often leads to better-informed decisions.',WEB),
  q(VD,'How can a delegate get the most from the Meet the Candidates Breakfast?','Prepare a few respectful questions',['Ask only about candidates’ hobbies','Avoid talking to any of the candidates','Promise votes to the candidates who ask'],'C','Thoughtful questions can show how candidates think and communicate under pressure.',WEB),
  q(VD,'When reading a candidate’s resume, what should a delegate look for most?','Specific accomplishments',['The number of titles listed','The design and colors of the page','The total length of the resume'],'D','Specific results show what a candidate has actually done, not just the offices they held.',WEB),
  q(VD,'Campaign rules limit how candidates may promote themselves at ILC. What is a delegate’s responsibility?','Know the rules and avoid encouraging violations',['Enforce the rules personally','Ignore them, since they apply only to candidates','Help candidates find ways around them'],'A','If a delegate sees a possible violation, it should be reported to the State Advisor or proper officials.',WEB),
  q(VD,'The Voting Delegate Test allows 60 minutes for 50 multiple-choice items and one essay. Which time plan is most practical?','About 40 minutes for the items and 15–20 for the essay',['About 55 minutes for the items and 5 for the essay','About 10 minutes for the items and 50 for the essay','Spend all 60 minutes on the items and skip the essay'],'B','Leaving a few minutes at the end allows a quick review of answers.',WEB),
  q(VD,'How should a delegate begin the tiebreaker essay?','With an introduction and a clear thesis',['With a list of every motion they know','With a joke unrelated to HOSA','With the conclusion and final summary first'],'C','Body paragraphs should then give specific points, such as delegate duties or motion rules.',WEB),
  q(VD,'During the Business Session, how should a delegate treat candidates they do not support?','With the same courtesy given to every candidate',['By ignoring them','By criticizing them to other delegates','By booing their speeches'],'D','Respectful behavior reflects well on the delegate and on their chartered association.',WEB),
  q(PP,'When the chair takes a voice vote, which words are used?','“Those in favor, say aye. Those opposed, say no.”',['“Those in favor, say yes. Those opposed, say nay.”','“Raise your hand if you agree.”','“Clap if you support the motion.”'],'A','Robert’s Rules uses “aye” and “no,” not “yes” and “nay,” in a voice vote.',BRIEF),
  q(PP,'How does a recess differ from adjourning?','A recess is a short break; the meeting then resumes',['A recess ends the meeting for the day','Adjourning is a short break in the meeting','They mean exactly the same thing'],'B','After a recess, business picks up exactly where it stopped, without a new call to order.',BRIEF),
  q(PP,'An amendment is pending on a main motion. What should debate focus on?','The amendment only',['The whole main motion','Any topic the speaker chooses','The previous meeting’s minutes'],'C','Once the amendment is decided, debate returns to the main motion.',BRIEF),
  q(PP,'A member objects to the consideration of a new main motion before debate begins. What vote sustains the objection?','Two-thirds voting against considering it',['A majority voting to consider it','A unanimous vote','No vote; the chair decides'],'D','An objection to consideration keeps an unwanted or embarrassing main motion from being discussed at all.',BRIEF),
  q(PP,'An organization has 60 members. A vote requires a majority of the entire membership. How many yes votes are needed?','31',['30','40','46'],'A','A majority of the entire membership is more than half of all members, whether or not they are present.',BRIEF),
  q(PP,'In a one-day meeting, when must the motion to reconsider be made?','On the same day the vote was taken',['At the next regular meeting','Within one week of the vote','At any time in the future'],'B','Reconsider must be made by a member who voted on the prevailing side.',BRIEF),
  q(PP,'After the chair has stated a motion, how can its maker withdraw it?','By asking the assembly’s permission',['By simply walking away','Only by a two-thirds vote','It can never be withdrawn once stated'],'C','Once stated, the motion belongs to the assembly, not to the maker alone.',BRIEF),
  q(PP,'The chair asks for general consent to approve a routine item, and one member objects. What happens next?','The chair takes a formal vote',['The item is adopted anyway','The item is dropped','The member must leave'],'D','General consent works only when no member objects; a single objection requires a vote.',BRIEF),
  q(PP,'In an election, 90 ballots are cast, and 6 are illegal ballots from legal voters. How many votes are needed for a majority?','46',['43','45','48'],'A','Illegal ballots cast by legal voters count in the total, so a majority of 90 is 46.',BRIEF),
  q(PP,'Does an appeal from the decision of the chair require a second?','Yes',['No','Only during elections','Only if the chair asks for one'],'B','The second shows that at least two members want the assembly to decide the question.',BRIEF),
  q(PP,'A motion reads “to hold a car wash and a bake sale.” A member moves to remove “and a bake sale.” Which form of amendment is this?','Strike out',['Insert','Substitute','Add'],'C','Striking out removes words, while insert and add put new words in.',BRIEF),
  q(PP,'May the maker of a motion speak against their own motion in debate?','No, though they may vote against it',['Yes, at any time during debate','Only if no one else wants to speak','Only with a two-thirds vote'],'D','A maker who changes their mind can also ask permission to withdraw the motion.',BRIEF),
  q(INC,'In a nonprofit corporation, which group usually approves the yearly budget?','The board of directors',['The members at large','Individual staff','The newest volunteers'],'A','The board is responsible for the organization’s legal and financial health.',HB),
  q(INC,'Which action fails to meet a nonprofit’s fiduciary responsibility?','Spending funds without keeping records',['Preparing a budget','Having an audit done','Adopting a conflict-of-interest policy'],'B','Budgets, financial reports, audits and conflict policies are key fiduciary practices.',HB),
  q(INC,'Which board group often acts for the full board between its meetings?','The executive committee',['The nominating committee','The audit committee','The social committee'],'C','Bylaws usually define what powers the executive committee has.',HB),
  q(INC,'Why are minutes of board meetings important for a nonprofit?','They officially record board decisions',['They replace the bylaws once approved','They list each member’s private opinions','They are needed only for social events'],'D','Accurate minutes show what was decided and support transparency and accountability.',HB),
  q(INC,'Why do organizations put many details in policy manuals rather than in their bylaws?','Policies are easier to update when needs change',['Policies outrank the bylaws in authority','Bylaws cannot include any rules at all','Policy manuals never need any approval'],'A','Bylaws need previous notice and a two-thirds vote to amend, so they hold only the most basic rules.',HB),
  q(INC,'A donor gives money to a nonprofit only for student scholarships. How must the organization use it?','Only for the purpose the donor set',['For any purpose the board chooses','For staff bonuses','For the next conference party'],'B','Honoring restrictions on gifts is part of fiduciary responsibility and ethical governance.',HB),
  q(INC,'A board approves an action that its articles of incorporation forbid. What is the status of that action?','It is invalid, because the charter ranks higher',['It is valid, since the board approved it','It is valid until the next meeting','It is valid if staff agree'],'C','Only applicable law ranks above an organization’s corporate charter.',HB),
  q(INC,'Where should a nonprofit board define its own quorum?','In the bylaws',['In a news release','In the budget','In staff job descriptions'],'D','The quorum is a basic rule that protects members, so it belongs in the bylaws.',HB),
  q(ORG,'A teacher wants to start a HOSA chapter at a new school. Whom should the teacher contact for guidance?','Their State Advisor',['The Executive Council president','The board of a local hospital','An advisor from a different CTSO'],'A','State Advisors coordinate chartered associations and the chapters within them.',HB),
  q(ORG,'Why are HOSA’s regions important for leadership?','Regions can be represented in leadership roles',['Regions replace chartered associations','Regions set membership dues','Regions write the bylaws'],'B','Members should learn which chartered associations belong to their region from the Handbook.',HB),
  q(ORG,'A member wins at the State Leadership Conference and qualifies for the next level. Which level hosts that competition?','The international level, at ILC',['The local chapter','The chartered association again','A regional hospital'],'C','The International Leadership Conference brings members from all chartered associations together each year.',HB),
  q(ORG,'Which of these is not one of HOSA’s membership divisions?','Graduate faculty',['Middle school','Secondary','Alumni'],'D','HOSA’s divisions are middle school, secondary, postsecondary/collegiate, alumni and professional.',HB),
  q(ORG,'At which conference do most chapter members compete before reaching ILC?','The State Leadership Conference',['The Meet the Candidates Breakfast','A board of directors meeting','The Recognition Session'],'A','State Leadership Conferences are held by chartered associations.',HB),
  q(ORG,'Which group at HOSA’s international level is made up of student officers?','The Executive Council',['HOSA Headquarters staff','The State Advisors','The governing boards of HOSA, Inc.'],'B','Headquarters staff and governing boards also lead at the international level.',HB),
  q(HIST,'HOSA was founded in 1976. In which year was its 10th anniversary?','1986',['1980','1996','2006'],'C','Practice counting from the founding year to find any anniversary on a timeline.',FFY),
  q(HIST,'How many years old was HOSA in 2025?','49',['25','50','51'],'D','HOSA turned 50 in 2026, the year its First Fifty Years publication celebrates.',FFY),
  q(HIST,'The HOSA Handbook describes HOSA’s identity items. Which of these is not one of them?','An official mascot',['The organization’s motto','The organization’s creed','The organization’s emblem'],'A','HOSA’s identity items are its mission, motto, creed, emblem and colors.',HB),
  q(HIST,'Which milestone belongs at the year 2026 on a HOSA timeline?','HOSA’s 50th anniversary',['HOSA’s founding','HOSA’s 25th anniversary','HOSA’s 10th anniversary'],'B','The First Fifty Years 1976–2026 tells the story of HOSA’s first five decades.',FFY),
  q(HIST,'A HOSA timeline includes a “membership milestone.” What does this usually describe?','Reaching a new total number of members',['Electing a new president','Adopting a new emblem','Moving an event between categories'],'C','Other tested milestones include first conferences, new divisions and new chartered associations.',FFY),
  q(HIST,'HOSA was founded during which major national celebration year?','The U.S. bicentennial',['The end of World War II','The first Moon landing','The year 2000 millennium'],'D','The United States celebrated 200 years of independence in 1976, the year HOSA was founded.',FFY),
  q(EC,'An Executive Council candidate says only, “I want to make HOSA better,” with no details. What is missing?','A clear, specific vision',['Professional attire','A long resume','Popularity with members'],'A','Strong candidates explain specific plans for serving members during their year in office.',HB),
  q(EC,'At ILC, an Executive Council officer follows the dress code and treats volunteers with respect. What does this show?','Modeling leadership for members',['Representing a region','Keeping records','Presiding over the Business Session'],'B','Officers set an example for members, so their conduct at conferences matters.',HB),
  q(EC,'Which activity is an example of an Executive Council officer promoting HOSA?','Speaking about HOSA to health care partners',['Grading competitive event tests at ILC','Setting membership dues for each state','Choosing each state’s voting delegates'],'C','Promoting HOSA helps build support, partnerships and membership growth.',HB),
  q(EC,'An officer stays after a session to help members find their next event, without seeking credit. Which quality does this show?','Servant leadership',['Reliability only','Knowledge of HOSA','Charisma'],'D','Servant leaders put members’ needs ahead of their own recognition.',HB),
  q(MEM,'A HOSA member graduates and wants to keep supporting HOSA. Which membership fits?','Alumni membership',['Middle school membership','Secondary membership','Postsecondary/collegiate competitor status'],'A','Lifetime alumni membership lets graduates stay connected after graduation.',HB),
  q(MEM,'May a professional member compete in Organizational Leadership?','No; professional members are not eligible',['Yes, in any division they choose','Yes, if they are under 30 years old','Only as the captain of a team'],'B','Professional members support student members rather than compete.',HB)
 ],9636)
};
